import { test, expect } from '@playwright/test';

test.describe('Password Authentication Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display error message when user enters incorrect password', async ({ page }) => {
    // Setup: intercept the password API call with an incorrect response
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Intercept the API call with a successful response
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Verify error message is visible
    const errorMessage = page.getByText('Invalid password');
    await expect(errorMessage).toBeVisible();

    // Verify error class is applied
    const errorClass = page.getByTestId('error-message');
    await expect(errorClass).toHaveClass(/error/);

    // Verify error message is displayed
    await expect(errorMessage).toContainText('Invalid password');

    // Verify password input has error state
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toHaveClass(/error/);

    // Verify password input is not empty
    await expect(passwordInput).toHaveValue('');

    // Verify login button is disabled
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeDisabled();
  });

  test('should clear error message when user enters correct password', async ({ page }) => {
    // Setup: intercept the password API call with an incorrect response
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Intercept the API call with a successful response
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Verify error message is visible initially
    const errorMessage = page.getByText('Invalid password');
    await expect(errorMessage).toBeVisible();

    // Verify error class is applied
    const errorClass = page.getByTestId('error-message');
    await expect(errorClass).toHaveClass(/error/);

    // Verify error message is displayed
    await expect(errorMessage).toContainText('Invalid password');

    // Verify password input has error state
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toHaveClass(/error/);

    // Verify password input is not empty
    await expect(passwordInput).toHaveValue('');

    // Verify login button is disabled
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeDisabled();

    // Enter correct password
    await passwordInput.fill('correctPassword123');

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify error class is removed
    await expect(errorClass).not.toHaveClass(/error/);

    // Verify login button is enabled
    await expect(loginButton).not.toBeDisabled();

    // Verify password input no longer has error state
    await expect(passwordInput).not.toHaveClass(/error/);
  });
});
